import {Component, HostBinding, OnInit} from '@angular/core';
import {Router} from '@angular/router';
import {endOfDay, subDays} from 'date-fns';
import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {HttpClientService} from '../../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from '../../../environments/environment';
import {DatePipe} from '@angular/common';

const { Ocr } = Plugins;
@Component({
    selector: 'app-transfer-box-list',
    templateUrl: 'transfer-box-list.page.html',
    styleUrls: ['transfer-box-list.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class TransferBoxListPage implements OnInit {
    bottleList = [];
    SelectTime = 2;
    beginDate = endOfDay(subDays(new Date(), 1));
    endDate = endOfDay(new Date());
    timeList = [
        {id: 2, name: '2日内记录 '},
        {id: 3, name: '3日内记录 '},
        {id: 4, name: '4日内记录 '},
        {id: 5, name: '5日内记录 '},
        {id: 6, name: '6日内记录 '},
        {id: 7, name: '7日内记录 '},
        {id: 8, name: '8日内记录 '},
        {id: 9, name: '9日内记录 '},
        {id: 10, name: '10日内记录 '},
    ];
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private platform: Platform,
        private datePipe: DatePipe,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
        // 获取管列表
        this.ListBoxTube();
    }

    // 路由返回
    routeBack() {
       // this.router.navigate(['/BoxList']);
         this.router.navigate(['/tabs/tab1']);
    }
    changeTime(){
        this.beginDate = endOfDay(subDays(new Date(), this.SelectTime - 1));
        this.ListBoxTube();
    }

    // 调用后台接口
    // 根据箱查询所有管
    ListBoxTube(){
        this.bottleList = [];
        // const condition = {
        //     "beginDate": this.datePipe.transform(this.beginDate, 'yyyy-MM-dd HH:mm:ss'),
        //     "endDate": this.datePipe.transform(this.endDate, 'yyyy-MM-dd HH:mm:ss'),
        // };
        const condition = {
            "beginDate": this.beginDate,
            "endDate": this.endDate
        };
        this.http
            .post(`rcp/api/box/operate/listBoxTransferLog`, condition , '根据箱查询所有管', environment.FailMessage.getBoxTube)
            .subscribe( data => {
                if (data['isSuccess']){
                 this.bottleList = data['data'];
               }
            });
    }
}
